import React from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { TransformWrapper, TransformComponent } from "react-zoom-pan-pinch";

const Container = styled.div`
  padding: 20px;
  text-align: center;
`;

const Title = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const Controls = styled.div`
  margin-bottom: 10px;
  button {
    margin: 0 5px;
    padding: 6px 12px;
    font-size: 14px;
    cursor: pointer;
  }
`;

const Image = styled.img`
  max-width: 100%;
  height: auto;
  border-radius: 10px;
  border: 1px solid #ccc;
`;

const DatasetStatistic = () => {
  const { t } = useTranslation();

  return (
    <Container>
      <Title>{t("Dataset Statistic")}</Title>
      <TransformWrapper
        initialScale={1}
        minScale={0.5}
        maxScale={3}
        wheel={{ step: 0.1 }}
      >
        {({ zoomIn, zoomOut, resetTransform }) => (
          <>
            <Controls>
              <button onClick={() => zoomOut()}>{t("Zoom Out")}</button>
              <button onClick={() => zoomIn()}>{t("Zoom In")}</button>
              <button onClick={() => resetTransform()}>{t("Reset")}</button>
            </Controls>
            <TransformComponent>
              <Image src="/Statistic1.jpg" alt="Statistic" />
            </TransformComponent>
          </>
        )}
      </TransformWrapper>
    </Container>
  );
};

export default DatasetStatistic;
